def flame(cx, cy, h, k='m', k2='a'):
    """A flame/teardrop of height h centred on (cx, cy)."""
    t, b = cy - h // 2, cy + h // 2
    w = max(2, h // 3)
    return [(k, 'g', [(cx, t), (cx + w, cy), (cx + w - 1, b - 1), (cx, b), (cx - w + 1, b - 1), (cx - w, cy)]),
            (k2, 'g', [(cx, cy - h // 6), (cx + w // 2, cy + 1), (cx, b - 1), (cx - w // 2, cy + 1)])]

def leaf(cx, cy, w, h, k='m'):
    return [(k, 'g', [(cx, cy - h), (cx + w, cy), (cx, cy + h), (cx - w, cy)]), ('a', 'l', cx, cy - h + 1, cx, cy + h - 1)]

def puff(cx, cy, r=2, k='m'):
    return [(k, 'E', cx - r, cy - r, cx + r, cy + r), (k, 'E', cx - 2 * r + 1, cy - r + 1, cx - 1, cy + r + 1), (k, 'E', cx + 1, cy - r + 1, cx + 2 * r - 1, cy + r + 1)]

def star(cx, cy, r, k='w'):
    return [(k, 'l', cx - r, cy, cx + r, cy), (k, 'l', cx, cy - r, cx, cy + r)]

